S = "Hakeem Force Academy"
def syn(w, ans, wr, pos, ids, mean):
    o = list(wr)
    o.insert(pos, ans)
    return (S, "Which word is closest in meaning (a synonym) to " + w + "?", o, pos,
            mean, "A synonym is a word with almost the same meaning as another word.", ids)
